using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static partial class GardenBoundaryPrefabBuilder {
static void PlaceInTargetScene(){const string target="Assets/Scenes/Oasis/MobileOptimization/Gangstar City.unity";var sc=SceneManager.GetSceneByPath(target);if(!sc.IsValid()||!sc.isLoaded)sc=EditorSceneManager.OpenScene(target,OpenSceneMode.Additive);SceneManager.SetActiveScene(sc);var plot=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Single(r=>r.name=="polySurface47");var b=plot.bounds;var pos=new Vector3(b.center.x,b.max.y+.02f,b.center.z);var asset=AssetDatabase.LoadAssetAtPath<GameObject>(Output+"/Garden Perimeter - Palms and Illuminated Railing.prefab");if(!asset)throw new Exception("Garden perimeter prefab missing");string backup="FinalEnvironmentRoadBackup/BeforeGardenPerimeterPlacement";Directory.CreateDirectory(backup);if(!File.Exists(backup+"/Gangstar City.unity"))EditorSceneManager.SaveScene(sc,backup+"/Gangstar City.unity",true);var root=sc.GetRootGameObjects().FirstOrDefault(g=>g.name=="Garden Perimeter - polySurface47");if(!root)root=sc.GetRootGameObjects().FirstOrDefault(g=>PrefabUtility.GetCorrespondingObjectFromSource(g)==asset&&Vector3.Distance(g.transform.position,pos)<2);if(!root)root=(GameObject)PrefabUtility.InstantiatePrefab(asset,sc);root.name="Garden Perimeter - polySurface47";root.transform.SetPositionAndRotation(pos,Quaternion.identity);root.transform.localScale=Vector3.one;PrefabUtility.RecordPrefabInstancePropertyModifications(root.transform);PrefabUtility.RecordPrefabInstancePropertyModifications(root);EditorSceneManager.MarkSceneDirty(sc);if(!EditorSceneManager.SaveScene(sc,target))throw new Exception("Target scene save failed");Selection.activeGameObject=root;EditorGUIUtility.PingObject(root);var ctrl=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool was=ctrl.IsNight;try{foreach(bool night in new[]{false,true}){ctrl.Apply(night);var at=pos+Vector3.up*1.5f;var cam=at+new Vector3(b.size.x*.42f,b.size.z*.58f,-b.size.z*.60f);CityLightingBuilder.Capture(ctrl,Tuple.Create(cam,Quaternion.LookRotation(at-cam)),"Garden-Placed-"+(night?"Night":"Day"));}}finally{ctrl.Apply(was);}EditorSceneManager.SaveScene(sc,target);File.WriteAllText("FinalEnvironmentRoadReview/GardenPerimeterPlacement.txt","SUCCESS placed and saved in "+sc.path+". Root="+root.name+" position="+pos+". Existing prefab linked,18 palms,4 corner entrance gaps retained. Existing fountain, flowers,paths untouched. Added realtime lights="+root.GetComponentsInChildren<Light>(true).Length+". Single site instance="+sc.GetRootGameObjects().Count(g=>g.name==root.name)+". Use this target scene for further work.");}
